-- This catalog gate does not resolve or suppress the eight raw lint errors.
begin;
set local search_path=pg_catalog,extensions,pg_temp;
select plan(12);
select is(current_setting('server_version_num'),'170006','reviewed server PG 17.6; drift requires review');
select is((select extversion from pg_extension where extname='pgtap'),'1.3.3','reviewed upstream pgTAP version');
